/** Form submission that was created or retrieved. */
export interface FormSubmission {
  /**
   * Submission ID.
   * @format GUID
   * @readonly
   */
  _id?: string | null;
  /**
   * ID of the form which the submission belongs to.
   * @format GUID
   * @immutable
   */
  formId?: string;
  /**
   * The app which the form submissions belong to. A submission inherits the namespace from its form schema, so you can't set it directly.
   *
   * For example, a submission of a form visible in the Wix Forms app has the namespace `wix.form_app.form`, the namespace of the Wix Forms app, whose app ID is `225dd912-7dea-4738-8688-4b8c6955ffc2`.
   *
   * See a list of namespaces for [apps made by Wix](https://dev.wix.com/docs/api-reference/crm/forms/form-schemas/introduction#namespaces-of-apps-made-by-wix) section.
   * To retrieve the ID for a Wix app, see [Apps Created By Wix](https://dev.wix.com/docs/rest/articles/get-started/apps-created-by-wix).
   * @minLength 10
   * @maxLength 50
   * @readonly
   */
  namespace?: string;
  /**
   * Status of the submission.
   *
   * The status a submission is created with depends on the form's namespace and on whether the form collects payment, so read it from the response rather than assuming.
   *
   * A submission for a form that collects payment starts as `PAYMENT_WAITING`. Otherwise, most namespaces record the submission immediately as `CONFIRMED`. Namespaces that need to complete another step first, such as taking payment for a pricing plan, create the submission as `PENDING` and confirm it later with Confirm Submission.
   *
   * A `PENDING` submission isn't recorded yet, and is deleted automatically if it isn't confirmed in time.
   */
  status?: SubmissionStatusWithLiterals;
  /**
   * Values the visitor submitted.
   *
   * Each key is the `target` of a field in the form schema, which is the field's stable storage key rather than its ID or label. Only keys matching a field target are accepted.
   *
   * Each value's shape follows that field's `inputType`: `STRING` fields submit a string, `NUMBER` a number, `BOOLEAN` a boolean, and `ARRAY` an array of the selected option values. Date and time fields are strings. A choice field submits an option's `value`, not its ID or its label.
   *
   * 3 input types submit structured values: `ADDRESS` submits an address object, `PAYMENT` an array holding 1 product object per item bought, and `SCHEDULING` an appointment object.
   *
   * For the full mapping, see [About Submission Values](https://dev.wix.com/docs/api-reference/crm/forms/form-submissions/about-submission-values).
   */
  submissions?: Record<string, any>;
  /**
   * Date and time the form submission was created.
   * @immutable
   */
  _createdDate?: Date | null;
  /**
   * Date and time the form submission was updated.
   * @readonly
   */
  _updatedDate?: Date | null;
  /**
   * Revision number, which increments by 1 each time the form submission is updated. To prevent conflicting changes, the existing revision must be used when updating a form submission.
   * @readonly
   */
  revision?: string | null;
  /**
   * ID of the visitor that submitted the form.
   * @readonly
   */
  submitter?: Submitter;
  /** Whether a site owner marked a submission as "seen". */
  seen?: boolean;
  /** Data extension object that holds users' and apps' fields. */
  extendedFields?: ExtendedFields;
  /**
   * Order details. <br>
   * <b>Note</b>: This object is only applicable when submitting a form in the Wix Payments app.
   */
  orderDetails?: OrderDetails;
  /**
   * Contact ID of a site visitor who created the submission.
   * @format GUID
   * @immutable
   */
  contactId?: string | null;
  /**
   * Authorized viewer ID.
   * @format GUID
   * @immutable
   */
  accessRestriction?: string | null;
  /** Tag IDs collections associated with the current entity. */
  tags?: PublicTags;
  /**
   * Appointment details.
   * This object is only applicable when submitting a form that creates a booking appointment.
   */
  appointmentDetails?: AppointmentDetails;
  /**
   * ID of the child site the submission was made on.
   *
   * Only present when the form was submitted on a site that shares its data with a parent site. In that case submissions from every child site are stored on the parent site, and this field identifies which child site the submission came from.
   * @format GUID
   * @readonly
   */
  childMetaSiteId?: string | null;
}

export enum SubmissionStatus {
  /** A submission is created, but has not yet been recorded in the Wix Forms collection. */
  PENDING = 'PENDING',
  /** A submission is recorded in the Wix Forms collection. */
  CONFIRMED = 'CONFIRMED',
  /** A form submission requiring payment is created. */
  PAYMENT_WAITING = 'PAYMENT_WAITING',
  /** An order of a form submission is canceled. */
  PAYMENT_CANCELED = 'PAYMENT_CANCELED',
}

/** @enumType */
export type SubmissionStatusWithLiterals =
  | SubmissionStatus
  | 'PENDING'
  | 'CONFIRMED'
  | 'PAYMENT_WAITING'
  | 'PAYMENT_CANCELED';

